{
  "name": "godot",
  "description": "Generate production-ready GDScript 2.0 for Godot 4.3+ with strict static typing, official style guide compliance, and modern architecture patterns.",
  "version": "1.0.0",
  "contextFileName": "GEMINI.md"
}

{
  "hooks": {
    "SessionStart": [
      {
        "matcher": "startup|resume",
        "hooks": [
          {
            "type": "command",
            "command": "echo 'Godot skill available. Godot 4.3+ only. GDScript 2.0. Strict static typing. See skills/godot/SKILL.md.'",
            "timeout": 5,
            "statusMessage": "Loading godot skill..."
          }
        ]
      }
    ]
  }
}

{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "godot",
  "description": "Generate production-ready GDScript 2.0 for Godot 4.3+ with strict static typing, official style guide compliance, and modern architecture patterns.",
  "owner": {
    "name": "shihabshahrier",
    "url": "https://github.com/shihabshahrier"
  },
  "plugins": [
    {
      "name": "godot",
      "description": "Expert Godot 4 game dev assistant with strict GDScript 2.0 enforcement",
      "source": "./",
      "category": "developer-tools"
    }
  ]
}

